// Doorbell chime: a settled press sounds the chime for 300 ms.
// Chime driver on D7, doorbell button on D4 (pull-up), status over UART.

const int CHIME_PIN = 7;
const int BUTTON_PIN = 4;
const unsigned long CHIME_MS = 300;
const unsigned long REPORT_MS = 1000;
const int POLL_MS = 5;
const unsigned long SETTLE_MS = 20;

bool lowActive = false;
unsigned long lowStart = 0;
bool armed = true;
bool chiming = false;
unsigned long chimeStart = 0;
unsigned long lastReport = 0;
unsigned int rings = 0;

void startChime()
{
    chiming = true;
    chimeStart = millis();
    rings++;
    digitalWrite(CHIME_PIN, HIGH);
}

void endChime()
{
    chiming = false;
    digitalWrite(CHIME_PIN, LOW);
}

void pollButton()
{
    if (digitalRead(BUTTON_PIN) == LOW)
    {
        if (!lowActive)
        {
            lowActive = true;
            lowStart = millis();
        }
        if (armed && millis() - lowStart >= SETTLE_MS)
        {
            armed = false;
            if (!chiming)
            {
                startChime();
            }
        }
    }
    else
    {
        lowActive = false;
        armed = true;
    }
}

void report()
{
    Serial.print("chime n=");
    Serial.println(rings);
}

void setup()
{
    pinMode(CHIME_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    digitalWrite(CHIME_PIN, LOW);
    Serial.begin(9600);
    lastReport = millis();
}

void loop()
{
    pollButton();
    if (chiming && millis() - chimeStart >= CHIME_MS)
    {
        endChime();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
    delay(POLL_MS);
}

// Lift call panel: buzzer acknowledges a press, a status line shows the
// panel is alive. Buzzer on D11, call button on D5 (pull-up).

const int BUZZER_PIN = 11;
const int BUTTON_PIN = 5;
const unsigned long BUZZ_MS = 300;
const unsigned long SETTLE_MS = 15;
const unsigned long BEAT_MS = 500;

int rawLevel = HIGH;
bool held = false;
unsigned long rawChangedAt = 0;
unsigned long lastBeat = 0;
unsigned int beats = 0;

bool buzzing = false;
unsigned long buzzStartedAt = 0;

void acknowledge()
{
    digitalWrite(BUZZER_PIN, HIGH);
    buzzing = true;
    buzzStartedAt = millis();
}

void serviceBuzzer()
{
    if (buzzing && millis() - buzzStartedAt >= BUZZ_MS)
    {
        digitalWrite(BUZZER_PIN, LOW);
        buzzing = false;
    }
}

void scanButton()
{
    int level = digitalRead(BUTTON_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !buzzing)
        {
            acknowledge();
        }
        held = down;
    }
}

void heartbeat()
{
    beats++;
    Serial.print("alive ");
    Serial.println(beats);
}

void setup()
{
    pinMode(BUZZER_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    digitalWrite(BUZZER_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastBeat = millis();
}

void loop()
{
    scanButton();
    serviceBuzzer();
    if (millis() - lastBeat >= BEAT_MS)
    {
        lastBeat = millis();
        heartbeat();
    }
}

// Meadow sprinkler zone: one 500 ms burst per start press.
// Valve relay on D10, start button on D6 (pull-up), status over UART.

const int ZONE_PIN = 10;
const int START_PIN = 6;
const unsigned long BURST_MS = 500;
const unsigned long SETTLE_MS = 10;
const unsigned long REPORT_MS = 1000;

bool zoneOpen = false;
bool held = false;
int rawLevel = HIGH;
unsigned long rawChangedAt = 0;
unsigned long closeAt = 0;
unsigned long lastReport = 0;
unsigned int bursts = 0;

void openZone()
{
    zoneOpen = true;
    closeAt = millis() + BURST_MS;
    digitalWrite(ZONE_PIN, HIGH);
    bursts++;
}

void closeZone()
{
    zoneOpen = false;
    digitalWrite(ZONE_PIN, LOW);
}

bool closeDue()
{
    return (long)(millis() - closeAt) >= 0;
}

void scanStart()
{
    int level = digitalRead(START_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !zoneOpen)
        {
            openZone();
        }
        held = down;
    }
}

void report()
{
    Serial.print("zone n=");
    Serial.println(bursts);
}

void setup()
{
    pinMode(ZONE_PIN, OUTPUT);
    pinMode(START_PIN, INPUT_PULLUP);
    digitalWrite(ZONE_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanStart();
    if (zoneOpen && closeDue())
    {
        closeZone();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Orchard spray controller: one short burst per trigger press.
// Valve relay on D8, trigger button on D2 (pull-up), status over UART.

const int VALVE_PIN = 8;
const int TRIGGER_PIN = 2;
const unsigned long OPEN_MS = 400;
const unsigned long SETTLE_MS = 12;
const unsigned long REPORT_MS = 1000;

bool valveOpen = false;
bool pressed = false;
int rawLevel = HIGH;
unsigned long rawChangedAt = 0;
unsigned long valveDeadline = 0;
unsigned long lastReport = 0;
unsigned int bursts = 0;

void openValve()
{
    valveOpen = true;
    valveDeadline = millis() + OPEN_MS;
    digitalWrite(VALVE_PIN, HIGH);
    bursts++;
}

void closeValve()
{
    valveOpen = false;
    digitalWrite(VALVE_PIN, LOW);
}

bool deadlineReached()
{
    return millis() >= valveDeadline;
}

void scanTrigger()
{
    int level = digitalRead(TRIGGER_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !pressed)
        {
            if (!valveOpen)
            {
                openValve();
            }
            pressed = true;
        }
        else if (!down && pressed)
        {
            pressed = false;
        }
    }
}

void report()
{
    Serial.print("spray n=");
    Serial.print(bursts);
    Serial.print(" open=");
    Serial.println(valveOpen ? 1 : 0);
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(TRIGGER_PIN, INPUT_PULLUP);
    digitalWrite(VALVE_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanTrigger();
    if (valveOpen && deadlineReached())
    {
        closeValve();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Silo level gauge: running average of the level probe on A2.
// Full-level lamp on D6, level report over UART.

const int PROBE_PIN = A2;
const int LAMP_PIN = 6;
const int WINDOW = 40;
const long FULL_MM = 4200;
const unsigned long SAMPLE_MS = 25;
const unsigned long REPORT_MS = 1000;

int readings[WINDOW];
int slot = 0;
long total = 0;
unsigned long lastSample = 0;
unsigned long lastReport = 0;

void takeSample()
{
    int raw = analogRead(PROBE_PIN);
    total -= readings[slot];
    readings[slot] = raw;
    total += raw;
    slot = (slot + 1) % WINDOW;
}

long averageMm()
{
    return (total * 5000L) / (1023L * WINDOW);
}

void showLamp()
{
    digitalWrite(LAMP_PIN, averageMm() >= FULL_MM ? HIGH : LOW);
}

void report()
{
    Serial.print("level ");
    Serial.print(averageMm());
    Serial.println(" mm");
}

void setup()
{
    pinMode(LAMP_PIN, OUTPUT);
    digitalWrite(LAMP_PIN, LOW);
    Serial.begin(9600);
    for (int i = 0; i < WINDOW; i++)
    {
        readings[i] = 0;
    }
    for (int i = 0; i < WINDOW; i++)
    {
        takeSample();
    }
    lastSample = millis();
    lastReport = millis();
    showLamp();
}

void loop()
{
    unsigned long now = millis();
    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        takeSample();
        showLamp();
    }
    if (now - lastReport >= REPORT_MS)
    {
        lastReport = now;
        report();
    }
}

// Stair light: one press lights the stairs for three seconds.
// Relay on D9, push button on D2, mode switch on D3 (both pull-up).

const int LIGHT_PIN = 9;
const int BUTTON_PIN = 2;
const int MODE_PIN = 3;
const unsigned long LIT_MS = 3000;
const unsigned long SETTLE_MS = 15;
const unsigned long REPORT_MS = 1000;

bool lit = false;
bool held = false;
int rawLevel = HIGH;
int lastMode = HIGH;
unsigned long rawChangedAt = 0;
unsigned long litSince = 0;
unsigned long lastReport = 0;

void armTimer()
{
    litSince = millis();
}

void lightOn()
{
    lit = true;
    armTimer();
    digitalWrite(LIGHT_PIN, HIGH);
}

void lightOff()
{
    lit = false;
    digitalWrite(LIGHT_PIN, LOW);
}

void onModeChange(int mode)
{
    lastMode = mode;
}

void scanButton()
{
    int level = digitalRead(BUTTON_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !lit)
        {
            lightOn();
        }
        held = down;
    }
}

void report()
{
    Serial.print("stair mode=");
    Serial.print(lastMode == HIGH ? 1 : 0);
    Serial.print(" lit=");
    Serial.println(lit ? 1 : 0);
}

void setup()
{
    pinMode(LIGHT_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    pinMode(MODE_PIN, INPUT_PULLUP);
    digitalWrite(LIGHT_PIN, LOW);
    Serial.begin(9600);
    lastMode = digitalRead(MODE_PIN);
    rawChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanButton();
    int mode = digitalRead(MODE_PIN);
    if (mode != lastMode)
    {
        onModeChange(mode);
    }
    if (lit && millis() - litSince >= LIT_MS)
    {
        lightOff();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Tank mixer scheduler: 2 s of mixing in every 5 s cycle.
// Relay on D6, hold switch on D3 (pull-up).

const int MIXER_PIN = 6;
const int HOLD_PIN = 3;
const uint16_t RUN_MS = 2000;
const uint16_t CYCLE_MS = 5000;
const uint16_t HOLD_DEBOUNCE_MS = 40;

uint16_t nextRunAt = 0;
uint16_t stopRunAt = 0;
bool running = false;
unsigned int runCount = 0;

bool heldStable = false;
bool heldRaw = false;
uint16_t heldChangedAt = 0;

uint16_t tickNow()
{
    return (uint16_t)millis();
}

void announceRun()
{
    Serial.print("mix ");
    Serial.println(runCount);
}

void startRun(uint16_t now)
{
    running = true;
    runCount++;
    stopRunAt = now + RUN_MS;
    nextRunAt = now + CYCLE_MS;
    announceRun();
}

void stopRun()
{
    running = false;
}

bool held()
{
    return heldStable;
}

void updateHold(uint16_t now)
{
    bool raw = (digitalRead(HOLD_PIN) == LOW);
    if (raw != heldRaw)
    {
        heldRaw = raw;
        heldChangedAt = now;
    }
    if (heldRaw != heldStable && (uint16_t)(now - heldChangedAt) >= HOLD_DEBOUNCE_MS)
    {
        heldStable = heldRaw;
    }
}

void drive()
{
    bool on = running && !held();
    digitalWrite(MIXER_PIN, on ? HIGH : LOW);
}

void setup()
{
    pinMode(MIXER_PIN, OUTPUT);
    pinMode(HOLD_PIN, INPUT_PULLUP);
    digitalWrite(MIXER_PIN, LOW);
    Serial.begin(9600);
    heldRaw = (digitalRead(HOLD_PIN) == LOW);
    heldStable = heldRaw;
    heldChangedAt = tickNow();
    nextRunAt = tickNow() + CYCLE_MS;
}

void loop()
{
    uint16_t now = tickNow();
    updateHold(now);
    if (running)
    {
        if (now >= stopRunAt)
        {
            stopRun();
        }
    }
    else if (now >= nextRunAt)
    {
        startRun(now);
    }
    drive();
}
